    dma_single_data_mode_init(DMA0, DMA_CH5, &dma_struct);
    dma_channel_enable(DMA0, DMA_CH5);
}

/* --- 中断服务函数 (接管CPU叫回操作) --- */
void TIMER5_DAC_IRQHandler(void)
{
    /* 检查是否是 TIMER5 的更新中断 */
    if (timer_interrupt_flag_get(TIMER5, TIMER_INT_FLAG_UP) != RESET) {
        timer_interrupt_flag_clear(TIMER5, TIMER_INT_FLAG_UP);

        /* 防御性编程：确保指针非空且长度有效 */
        if (s_dac_data != 0 && s_dac_len > 0) {

            /* 将数据写入对应通道 (使用标准库API替换直接操作寄存器) */
            if (s_dac_current_pin == GPIO_PIN_4) {
                dac_data_set(DAC0, DAC_OUT0, DAC_ALIGN_8B_R, s_dac_data[s_dac_index]);
            } else if (s_dac_current_pin == GPIO_PIN_5) {
                dac_data_set(DAC0, DAC_OUT1, DAC_ALIGN_8B_R, s_dac_data[s_dac_index]);
            }

            /* 游标自增并循环 */
            s_dac_index++;
            if (s_dac_index >= s_dac_len) {
                s_dac_index = 0;
            }
        }
    }
}
extern uint32_t SystemCoreClock;

/**
 * @brief  动态设置 DAC 输出波形的频率 (全整型高频优化版)
 * @param  dac_periph: DAC 外设 (如 DAC0)
 * @param  freq:       期望输出的完整波形频率 (单位: Hz)
 */
void GD32_DAC_TIM5_Base(uint32_t dac_periph, uint32_t freq)
{
    /* 1. 防御性检查 */
    if (freq == 0 || s_dac_len == 0) {
        return;
    }

    /* 2. 计算定时器实际需要的触发频率 */
    uint32_t target_trig_freq = freq * s_dac_len;

    /* 3. 获取 TIMER5 的时钟源频率 (GD32F4的APB1定时器通常为 SystemCoreClock / 2) */
    uint32_t timer_clk = SystemCoreClock / 2;

    /* 4. 计算总时钟分频系数 (使用四舍五入的整型除法技巧，提高精度) */
    uint32_t total_div = (timer_clk + (target_trig_freq / 2)) / target_trig_freq;

    if (total_div == 0) {
        total_div = 1;
    }

    /* 5. 动态分配 PSC 和 ARR (TIMER5 为16位定时器) */
    uint32_t psc = 0;
    uint32_t arr = 0;

    if (total_div <= 65536) {
        psc = 0;
        arr = total_div - 1;
    } else {
        psc = (total_div / 65536);
        arr = (total_div / (psc + 1)) - 1;
    }

    /* 6. 更新 TIMER5 的配置 */
    timer_prescaler_config(TIMER5, psc, TIMER_PSC_RELOAD_NOW);
    timer_autoreload_value_config(TIMER5, arr);
}

void bsp_dac_start_sawtooth_wave(uint32_t frequency) {
    bsp_dac_generate_sawtooth_wave();

    // 配置 DAC 和 DMA
    rcu_periph_clock_enable(RCU_DAC);
    rcu_periph_clock_enable(RCU_DMA1);

    dac_deinit();
    dac_trigger_source_config(DAC0, DAC_TRIGGER_T5_TRGO);
    dac_trigger_enable(DAC0);
    dac_wave_mode_config(DAC0, DAC_WAVE_DISABLE);
    dac_output_buffer_enable(DAC0);

    dma_single_data_parameter_struct dma_init_struct;
    dma_single_data_para_struct_init(&dma_init_struct);
    dma_init_struct.periph_addr = (uint32_t)&DAC0_R12DH;
    dma_init_struct.periph_inc = DMA_PERIPH_INCREASE_DISABLE;
    dma_init_struct.memory0_addr = (uint32_t)sawtooth_wave;
    dma_init_struct.memory_inc = DMA_MEMORY_INCREASE_ENABLE;
    dma_init_struct.periph_memory_width = DMA_PERIPH_WIDTH_16BIT;
    dma_init_struct.direction = DMA_MEMORY_TO_PERIPH;
    dma_init_struct.number = SAWTOOTH_RESOLUTION;
    dma_init_struct.priority = DMA_PRIORITY_HIGH;
    dma_init_struct.circular_mode = DMA_CIRCULAR_MODE_ENABLE;

    dma_deinit(DMA1, DMA_CH2);
    dma_single_data_mode_init(DMA1, DMA_CH2, &dma_init_struct);
    dma_channel_enable(DMA1, DMA_CH2);

    dac_dma_enable(DAC0);

    // 配置定时器
    rcu_periph_clock_enable(RCU_TIMER5);
    timer_deinit(TIMER5);

    timer_parameter_struct timer_initpara;
    timer_struct_para_init(&timer_initpara);
    timer_initpara.prescaler = 108 - 1; // 假设 108MHz 时钟，分频到 1MHz
    timer_initpara.alignedmode = TIMER_COUNTER_EDGE;
    timer_initpara.counterdirection = TIMER_COUNTER_UP;
    timer_initpara.period = (1000000 / frequency) - 1; // 计算周期
    timer_initpara.clockdivision = TIMER_CKDIV_DIV1;
    timer_initpara.repetitioncounter = 0;
    timer_init(TIMER5, &timer_initpara);

    timer_master_output_trigger_source_select(TIMER5, TIMER_TRI_OUT_SRC_UPDATE);
    timer_enable(TIMER5);

    dac_enable(DAC0);
}
